-- Morning feed pages: one read-only "page" per (user, domain cell, seen date), shown on the watch
-- home. Content is imported, never generated by the API. Additive and idempotent; no existing row
-- is touched.
CREATE TABLE IF NOT EXISTS public.morning_pages (
  user_id    uuid         NOT NULL,
  cell       varchar(50)  NOT NULL,
  seen_date  date         NOT NULL,
  headline   text         NOT NULL,
  core       jsonb        NOT NULL,
  note       jsonb        NOT NULL,
  videos     jsonb        NOT NULL,
  origin     varchar(32)  NOT NULL DEFAULT 'import',
  created_at timestamptz  NOT NULL DEFAULT now(),
  updated_at timestamptz  NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, cell, seen_date)
);

-- Write paths (grep "morning_pages" src scripts):
--   morning_pages: the only writer is scripts/morning-pages/import-page.ts (INSERT ... ON CONFLICT
--   (user_id, cell, seen_date) DO UPDATE, preview by default, --write to apply, staging only).
--   src/modules/morning-feed/pages.ts and the /pages routes only read.
-- Rollback: DROP TABLE public.morning_pages;
NOTIFY pgrst, 'reload schema';
